const b = $json.body ?? $json;
const required = ['assignmentId','dealId','closingOutcome'];
const missing = required.filter(k => b[k] === undefined || b[k] === null || b[k] === '');
if (missing.length) throw new Error('Missing required closing completion fields: ' + missing.join(', '));
const allowed = new Set(['closed','cancelled','failed','rescheduled','pending']);
const closingOutcome = String(b.closingOutcome).toLowerCase();
if (!allowed.has(closingOutcome)) throw new Error('Unsupported closing outcome: ' + closingOutcome);
const idempotencyKey = String(b.idempotencyKey ?? ('wf389:closing-completion:' + String(b.assignmentId) + ':' + String(b.dealId) + ':' + closingOutcome + ':' + String(b.eventId ?? 'default')));
return [{ json: { ...b, assignmentId: String(b.assignmentId), dealId: String(b.dealId), closingOutcome, idempotencyKey } }];

const ctx = $json;
const assignment = ctx.assignment ?? ctx.data?.assignment ?? {};
const deal = ctx.deal ?? ctx.data?.deal ?? {};
const approval = ctx.approval ?? ctx.data?.approval ?? {};
const closing = ctx.closing ?? ctx.data?.closing ?? {};
const blocked = new Set(['cancelled','disputed','dnc']);
const dealState = String(deal.state ?? deal.status ?? '').toLowerCase();
const assignmentState = String(assignment.state ?? assignment.status ?? '').toLowerCase();
const approvalStatus = String(approval.status ?? approval.decision ?? '').toLowerCase();
const closingStatus = String(closing.status ?? '').toLowerCase();
const issues = [];
if (approvalStatus !== 'approved') issues.push('assignment_approval_not_confirmed');
if (['closed'].includes(dealState) && $json.closingOutcome !== 'closed') issues.push('deal_already_closed');
if (blocked.has(dealState)) issues.push('deal_state_blocked:' + dealState);
if (blocked.has(assignmentState) && $json.closingOutcome !== 'cancelled') issues.push('assignment_state_blocked:' + assignmentState);
if ($json.closingOutcome === 'closed' && closingStatus === 'cancelled') issues.push('closing_already_cancelled');
const requiredForClose = ['closingCompletedAt','fundsConfirmed','buyerFundsConfirmed','sellerPayoffConfirmed'];
if ($json.closingOutcome === 'closed') {
  for (const field of requiredForClose) {
    if (field === 'closingCompletedAt' && !$json[field] && !closing.completedAt) issues.push('missing_closing_completed_at');
    if (field !== 'closingCompletedAt' && $json[field] !== true && closing[field] !== true) issues.push(field + '_not_confirmed');
  }
}
const valid = issues.length === 0;
return [{ json: { ...$json, assignment, deal, approval, closing, dealState, assignmentState, approvalStatus, closingStatus, issues, valid } }];
